const $ = (s) => document.querySelector(s);
function readStoredJson(key, fallback=null){const raw=localStorage.getItem(key);if(!raw)return fallback;try{return JSON.parse(raw)}catch(error){console.warn(`Discarding invalid saved value for ${key}.`,error);localStorage.removeItem(key);return fallback}}
const deepLinkPage = typeof location!=='undefined' && ['offers','logistics','buyers'].includes(new URLSearchParams(location.search).get('page')) ? new URLSearchParams(location.search).get('page') : null;
const state = { lang: localStorage.getItem('agri_lang') || 'fil', page: deepLinkPage || 'home', pendingPage:deepLinkPage, focusOffer:typeof location!=='undefined'?new URLSearchParams(location.search).get('offer'):null, mode: 'login', user: readStoredJson('agri_user'), token: localStorage.getItem('agri_token') || '' };
function shouldPreserveFormInput(){if(typeof document==='undefined')return false;const active=document.activeElement;if(active?.matches?.('input,textarea,select'))return true;if(Date.now()<(state.formInteractionUntil||0))return true;const root=$('#app');if(!root?.querySelectorAll)return false;return [...root.querySelectorAll('input,textarea,select')].some(control=>{if(control.disabled)return false;if(control.matches?.('input[type="checkbox"],input[type="radio"]'))return control.checked!==control.defaultChecked;if(control.tagName==='SELECT')return [...control.options].some(option=>option.selected!==option.defaultSelected);return control.value!==control.defaultValue})}
if(typeof document!=='undefined'&&document.addEventListener){const protectForm=event=>{if(event.target?.matches?.('input,textarea,select'))state.formInteractionUntil=Date.now()+60000};document.addEventListener('pointerdown',protectForm,true);document.addEventListener('input',protectForm,true);document.addEventListener('change',protectForm,true)}
const isEn = () => state.lang === 'en';
const dialectText={
  ceb:{'Wika':'Pinulongan','Bahay':'Balay','Presyo':'Presyo','Mamimili':'Mamalitay','Kooperatiba':'Kooperatiba','Plano':'Plano','Gabay':'Giya','Mga Serbisyo':'Mga Serbisyo','Presyo Ngayon':'Presyo Karon','Tingnan lahat':'Tan-awa tanan','Ilista ang Ani':'Ilista ang Ani','Magandang araw':'Maayong adlaw','Magsasaka':'Mag-uuma','Profile':'Profile','Pamayanan':'Komunidad','Pananim':'Tanom','Lokasyon':'Lokasyon'},
  ilo:{'Wika':'Pagsasao','Bahay':'Balay','Presyo':'Presyo','Mamimili':'Gumatang','Kooperatiba':'Kooperatiba','Plano':'Plano','Gabay':'Bagnos','Mga Serbisyo':'Dagiti Serbisyo','Presyo Ngayon':'Presyo Ita','Tingnan lahat':'Kitaen amin','Ilista ang Ani':'Ilista ti Apit','Magandang araw':'Naimbag nga aldaw','Magsasaka':'Mannalon','Profile':'Profile','Pamayanan':'Komunidad','Pananim':'Mula','Lokasyon':'Lugar'},
  hil:{'Wika':'Hambal','Bahay':'Balay','Presyo':'Presyo','Mamimili':'Manugbakal','Kooperatiba':'Kooperatiba','Plano':'Plano','Gabay':'Giya','Mga Serbisyo':'Mga Serbisyo','Presyo Ngayon':'Presyo Subong','Tingnan lahat':'Tan-awon tanan','Ilista ang Ani':'Ilista ang Ani','Magandang araw':'Maayong adlaw','Magsasaka':'Mangunguma','Profile':'Profile','Pamayanan':'Komunidad','Pananim':'Tanum','Lokasyon':'Lokasyon'}
};
const t = (fil, en) => isEn() ? en : state.lang==='fil' ? fil : (dialectText[state.lang]?.[fil]||fil);
const esc = (value = '') => String(value).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function icon(name, size=20){const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1Z"/><path d="M9 21v-7h6v7"/>',market:'<path d="M4 9h16l-1 12H5L4 9Z"/><path d="M3 9 5 3h14l2 6M8 13h8"/>',sparkle:'<path d="m12 2 1.8 6.2L20 10l-6.2 1.8L12 18l-1.8-6.2L4 10l6.2-1.8L12 2Z"/><path d="m19 16 .7 2.3L22 19l-2.3.7L19 22l-.7-2.3L16 19l2.3-.7L19 16Z"/>',community:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a5 5 0 0 1 10 0v2M16 11a3 3 0 1 0-1-5.8M16 16a5 5 0 0 1 5 5"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',map:'<path d="m9 18-6 3V6l6-3 6 3 6-3v15l-6 3-6-3Z"/><path d="M9 3v15M15 6v15"/>',plus:'<circle cx="12" cy="12" r="9"/><path d="M12 8v8M8 12h8"/>',trend:'<path d="m4 16 6-6 4 4 6-7"/><path d="M15 7h5v5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/>',back:'<path d="m15 18-6-6 6-6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',camera:'<path d="M4 7h3l2-3h6l2 3h3v12H4Z"/><circle cx="12" cy="13" r="3"/>',mic:'<rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3M8 21h8"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',chevron:'<path d="m9 18 6-6-6-6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.42 1.42M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.42-1.42M17.66 6.34l1.41-1.41"/>',jar:'<path d="M7 3h10M8 3v4l-2 3v9a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2v-9l-2-3V3M6 12h12M9 16h6"/>',sauce:'<path d="M9 3h6l1 4 2 3v9a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2v-9l2-3 1-4ZM8 8h8M9 14h6"/>',grain:'<path d="M12 22V7M12 11c-4 0-6-2-6-5 4 0 6 2 6 5ZM12 16c-4 0-6-2-6-5 4 0 6 2 6 5ZM12 11c4 0 6-2 6-5-4 0-6 2-6 5ZM12 16c4 0 6-2 6-5-4 0-6 2-6 5Z"/>'}[name]||'';return `<svg class="ui-icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`}
const crops = [{id:'palay',fil:'Palay',en:'Rice (palay)',base:27},{id:'mais',fil:'Mais',en:'Corn',base:18},{id:'kamatis',fil:'Kamatis',en:'Tomato',base:52},{id:'sibuyas',fil:'Sibuyas',en:'Onion',base:64},{id:'saging',fil:'Saging',en:'Banana',base:24},{id:'talong',fil:'Talong',en:'Eggplant',base:48},{id:'sili',fil:'Sili',en:'Chili pepper',base:95},{id:'pechay',fil:'Pechay',en:'Bok choy',base:42},{id:'repolyo',fil:'Repolyo',en:'Cabbage',base:38},{id:'patatas',fil:'Patatas',en:'Potato',base:70},{id:'kamote',fil:'Kamote',en:'Sweet potato',base:36},{id:'mangga',fil:'Mangga',en:'Mango',base:65},{id:'pinya',fil:'Pinya',en:'Pineapple',base:35},{id:'papaya',fil:'Papaya',en:'Papaya',base:32},{id:'niyog',fil:'Niyog',en:'Coconut',base:28}];
const cropPhoto=(crop,className='crop-photo')=>`<img class="${className}" src="assets/crops/${crop.id}.jpg" alt="" loading="lazy">`;
const cropPhotoById=(id,className='crop-photo')=>{const crop=crops.find(item=>item.id===id);return crop?cropPhoto(crop,className):''};
const harvests = [
  {crop:'Palay RC 222',qty:'1,200 kg',date:'Hulyo 12–16',enDate:'July 12–16',place:'Binalonan, Pangasinan',farmer:'Mang Tomas dela Cruz',grade:'Premium',emoji:'🌾'},
  {crop:'Kamatis Diamante',qty:'500 kg',date:'Hulyo 18',enDate:'July 18',place:'La Trinidad, Benguet',farmer:'Aling Rosa Santos',grade:'Class A',emoji:'🍅'},
  {crop:'Mais Hybrid',qty:'850 kg',date:'Hulyo 22–25',enDate:'July 22–25',place:'Bustos, Bulacan',farmer:'Jose Ramirez',grade:'Grade 1',emoji:'🌽'}
];
const coops = [
  {name:'Banaue Organic Rice Coop',place:'Banaue, Ifugao',dist:'2.4 km',members:'245',tags:['Patubig','Butil Dryer','Micro-loans']},
  {name:'Benguet Highland Producers',place:'La Trinidad, Benguet',dist:'5.1 km',members:'480',tags:['Logistics','Cold Storage','Organic Seeds']}
];
function api(path, body) { return fetch(path,{method:'POST',headers:{'Content-Type':'application/json',...(state.token?{Authorization:`Bearer ${state.token}`}:{})},body:JSON.stringify(body||{})}).then(async r=>{const data=await r.json();if(!r.ok)throw new Error(data.error||'May naganap na problema.');return data;}); }
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function selectLanguage(code){if(!['fil','en','ceb','ilo','hil'].includes(code))return;state.lang=code;state.languageOpen=false;localStorage.setItem('agri_lang',code);if(document.documentElement)document.documentElement.lang=code;render()}
function toggleLanguageMenu(){state.languageOpen=!state.languageOpen;render()}
function authHeader(){const names={fil:'Tagalog',en:'English',ceb:'Cebuano',ilo:'Ilocano',hil:'Hiligaynon'};return `<div class="language-picker"><button type="button" class="language-toggle" onclick="toggleLanguageMenu()" aria-expanded="${!!state.languageOpen}" aria-haspopup="menu">🌐 ${t('Wika','Language')}</button>${state.languageOpen?`<div class="language-menu" role="menu" aria-label="${t('Pumili ng wika','Choose a language')}">${Object.entries(names).map(([code,name])=>`<button type="button" class="${state.lang===code?'active':''}" onclick="selectLanguage('${code}')"><span>${name}</span>${state.lang===code?'✓':''}</button>`).join('')}<small>${t('Ang Cebuano, Ilocano, at Hiligaynon ay beta; ang ilang teksto ay maaaring manatiling Tagalog.','Cebuano, Ilocano, and Hiligaynon are in beta; some text may remain in Tagalog.')}</small></div>`:''}</div>`}
function splash(){return `<section class="splash"><div><img src="assets/logo.jpg" alt="AgrikAIzen logo"><h1>AgrikAIzen</h1><p>${t('AI gabay para sa magsasakang Pilipino','AI guidance for Filipino farmers')}</p><div class="spin"></div></div></section>`}
function auth(){const register=state.mode==='register';return `<section class="auth"><div class="brand"><img src="assets/logo.jpg" alt="AgrikAIzen"><h1>AgrikAIzen</h1><p>${t('Mas matalinong pagsasaka, mas siguradong kita.','Smarter farming, steadier income.')}</p></div><form class="auth-card" onsubmit="submitAuth(event)">
  <div class="title-row"><div><div class="eyebrow">${register?t('Bagong account','New account'):t('Maligayang pagbabalik','Welcome back')}</div><h2>${register?t('Sumali sa AgrikAIzen','Join AgrikAIzen'):t('Mag-log in','Sign in')}</h2></div>${authHeader()}</div>
  ${register?`<div class="field"><label for="name">${t('Buong pangalan','Full name')}</label><input id="name" required maxlength="80" autocomplete="name" placeholder="${t('hal. Mang Tomas dela Cruz','e.g. Tomas dela Cruz')}"></div><div class="field"><label for="accountLocation">${t('Lokasyon','Location')}</label><input id="accountLocation" name="address-level2" required maxlength="100" autocomplete="address-level2" placeholder="${t('hal. Binalonan, Pangasinan','e.g. Binalonan, Pangasinan')}"></div><div class="field"><label>${t('Piliin ang iyong tungkulin','Choose your role')}</label><div class="role-grid">${roleChoice('farmer','🌾',t('Magsasaka','Farmer'))}${roleChoice('buyer','🛒',t('Mamimili','Buyer'))}${roleChoice('coop','🤝',t('Kooperatiba','Cooperative'))}${roleChoice('logistics','🚚',t('Logistics partner','Logistics partner'))}</div></div>`:''}
  <div class="field"><label>Email</label><input id="email" type="email" required autocomplete="email" placeholder="pangalan@email.com"></div><div class="field"><label>${t('Password','Password')}</label><input id="password" type="password" required minlength="8" autocomplete="${register?'new-password':'current-password'}" placeholder="${t('Hindi bababa sa 8 karakter','At least 8 characters')}"></div>
  <button class="btn wide" id="authSubmit" type="submit">${register?t('Gumawa ng account','Create account'):t('Mag-log in','Sign in')}</button><p class="auth-switch">${register?t('May account ka na?','Already have an account?'):'New to AgrikAIzen?'} <button class="link" type="button" onclick="toggleAuth()">${register?t('Mag-log in','Sign in'):t('Magrehistro','Create an account')}</button></p>
  <p class="notice">${t('Ang AI price estimate ay gabay lamang batay sa ibinigay na impormasyon. I-verify ang presyo bago magbenta.','AI price estimates are guidance based on the information provided. Verify prices before selling.')}</p>
</form></section>`}
function roleChoice(id,icon,label){return `<button class="role ${state.selectedRole===id?'active':''}" onclick="setRole('${id}')" type="button"><span>${icon}</span><b>${label}</b></button>`}
function setRole(role){state.selectedRole=role;document.querySelectorAll('.role').forEach(button=>button.classList.toggle('active',button.getAttribute('onclick')===`setRole('${role}')`))} function toggleAuth(){state.mode=state.mode==='login'?'register':'login';state.selectedRole='farmer';render()}
async function submitAuth(e){e.preventDefault();const b=$('#authSubmit');b.disabled=true;b.textContent=t('Sandali…','Please wait…');try{const data=await api(`/api/auth/${state.mode}`,{name:$('#name')?.value,location:$('#accountLocation')?.value,role:state.selectedRole||'farmer',email:$('#email').value,password:$('#password').value});state.user=data.user;state.token=data.token;localStorage.setItem('agri_user',JSON.stringify(data.user));localStorage.setItem('agri_token',data.token);state.page=state.pendingPage||'home';state.pendingPage=null;state.draft=null;state.listingEstimate=null;refreshMarket();render();toast(t('Handa na ang iyong account!','Your account is ready!'))}catch(err){toast(err.message);b.disabled=false;b.textContent=state.mode==='register'?t('Gumawa ng account','Create account'):t('Mag-log in','Sign in')}}
function header(){const u=state.user||{};return `<header class="hero"><div class="hero-top"><img class="logo-mini" src="assets/logo.jpg" alt="AgrikAIzen logo"><b>AgrikAIzen</b>${authHeader()}<div class="header-actions">${state.user?.role==='farmer'?offerBell():''}<button class="circle account-button" onclick="go('profile')" aria-label="${t('Buksan ang account','Open account')}" title="${t('Account','Account')}">${icon('profile',24)}</button></div></div><h1>${t('Magandang araw','Good day')}, ${esc((u.name||'Kaibigan').split(' ')[0])}!</h1><p class="welcome">${roleName(u.role)} ${t('na handang umunlad','ready to grow')}</p><div class="location">⌖ ${esc(u.location||'Pilipinas')}</div></header>`}
function roleName(role){return {farmer:t('Magsasaka','Farmer'),buyer:t('Mamimili','Buyer'),coop:t('Kooperatiba','Cooperative'),logistics:t('Logistics partner','Logistics partner'),admin:'Admin'}[role]||t('Miyembro','Member')}
function nav(){let items;if(state.user?.role==='buyer')items=[['home','home',t('Bahay','Home')],['harvests','calendar',t('Ani','Harvests')],['offers','bell',t('Mga Alok','Deals')],['community','community',t('Pamayanan','Community')],['profile','profile',t('Ako','Profile')]];else if(state.user?.role==='logistics')items=[['home','home',t('Bahay','Home')],['logistics','market',t('Mga biyahe','Jobs')],['community','community',t('Pamayanan','Community')],['profile','profile',t('Ako','Profile')]];else if(state.user?.role==='coop')items=[['home','home',t('Bahay','Home')],['logistics','market',t('Transport','Transport')],['community','community',t('Pamayanan','Community')],['profile','profile',t('Ako','Profile')]];else items=[['home','home',t('Bahay','Home')],['buyers','market',t('Mamimili','Buyers')],['estimate','sparkle',t('AI Presyo','AI Price')],['community','community',t('Pamayanan','Community')],['profile','profile',t('Ako','Profile')]];return `<nav class="nav" aria-label="${t('Pangunahing menu','Main menu')}">${items.map(([id,i,l])=>`<button aria-label="${esc(l)}" class="${state.page===id?'active':''}" onclick="go('${id}')"><span>${icon(i,24)}</span><b>${l}</b></button>`).join('')}</nav>`}
function home(){if(state.user?.role==='buyer') return buyerHome(); if(state.user?.role==='logistics') return logisticsPage(); if(state.user?.role==='coop') return coopHome();const services=[['submit','plus',t('Ilista ang Ani','List harvest'),t('Ibenta ang iyong ani','List your crops for sale')],['prices','trend',t('Presyo','Prices'),t('Lahat ng presyo ngayon','All prices today')],['buyers','community',t('Mamimili','Buyers'),t('Mga buyer at kanilang kailangan','Buyers and their needs')],['coops','community',t('Kooperatiba','Cooperatives'),t('Samahan ng mga magsasaka','Farmer network')],['plan','calendar',t('Plano sa Pagtatanim','Crop Plan'),t('Kailan magtanim at mag-ani','When to plant and harvest')],['oversupply','book',t('Gabay','Guide'),t('Mga payo sa pagsasaka','Farming tips')]];return `<section class="page dashboard">${header()}<section class="insight-hero"><span>${icon('sparkle',18)} ${t('Bagong Harvest Insights','New harvest insights')}</span><h2>${t('Presyo ay alamin bago magbenta','Know prices before selling')}</h2><p>${t('Makakuha ng patas na market rate mula sa AgrikAIzen.','Get fair market rates generated by AgrikAIzen.')}</p></section><div class="section-title"><h2>${t('Presyo Ngayon','Today’s prices')}</h2><button class="link view-all" onclick="go('prices')">${t('Tingnan lahat','View all')} →</button></div><div class="price-row market-cards">${crops.slice(0,3).map(c=>`<button class="price" onclick="openPriceEstimator('${c.id}',${c.base},${c.base})" aria-label="${esc(t(`Buksan ang AI price estimator para sa ${c.fil}`,`Open AI price estimator for ${c.en}`))}">${cropPhoto(c,'crop-icon-photo')}<b>${isEn()?c.en:c.fil}</b><strong>₱${c.base}/kg</strong><small>${t('Kunin ang tantiya','Get estimate')}</small></button>`).join('')}</div><div class="section-title"><h2>${t('Mga Serbisyo','Services')}</h2></div><div class="service-grid">${services.map(s=>`<button class="service" onclick="go('${s[0]}')"><i>${icon(s[1],24)}</i><b>${s[2]}</b><small>${s[3]}</small><span class="service-next">›</span></button>`).join('')}</div></section>`}
function coopHome(){return `<section class="page dashboard">${header()}<section class="card buyer-callout"><div class="eyebrow">${t('Cooperative center','Cooperative center')}</div><h2>${t('Palaguin ang inyong komunidad','Grow your farming community')}</h2><p class="muted">${t('Iugnay ang mga miyembro sa mga buyer at patas na market insight.','Connect members with buyers and fair market insight.')}</p></section><section class="stat-grid"><div class="stat"><b>28</b><span>${t('Miyembro','Members')}</span></div><div class="stat"><b>12</b><span>${t('Ani','Harvests')}</span></div><div class="stat"><b>4</b><span>${t('Buyer','Buyers')}</span></div></section><div class="section-title"><h2>${t('Mga serbisyo','Services')}</h2></div><div class="service-grid"><button class="service" onclick="go('harvests')"><i>🌾</i><b>${t('Mga Ani','Harvests')}</b><small>${t('Mga paparating na supply','Upcoming supply')}</small></button><button class="service" onclick="go('map')"><i>⌖</i><b>${t('Mapa ng miyembro','Member map')}</b><small>${t('Mga lokasyon','Locations')}</small></button></div></section>`}
function harvestCard(h){return `<article class="card harvest"><div class="row"><div style="font-size:2rem">${h.emoji}</div><div class="grow"><div class="row between"><h3>${h.crop}</h3><span class="pill">${h.grade}</span></div><p class="muted">${h.qty} · ${h.place}</p><p class="small">${t('Ani','Harvest')}: <b>${isEn()?h.enDate:h.date}</b> · ${h.farmer}</p></div></div><button class="btn soft wide" onclick="contact('${esc(h.farmer)}')">${t('Makipag-ugnayan','Contact farmer')}</button></article>`}
function coopsPage(){const query=(state.coopQuery||'').toLowerCase();const list=[...coops].filter(c=>`${c.name} ${c.place} ${c.tags.join(' ')}`.toLowerCase().includes(query)).sort((a,b)=>Number(a.dist)-Number(b.dist));return `<section class="page soft-page"><div class="topbar"><button class="back" onclick="go('home')">${icon('back')}</button><h1>${t('Maghanap ng Katuwang','Find a Partner')}</h1>${authHeader()}</div><div class="input-row"><input value="${esc(state.coopQuery||'')}" oninput="searchCoops(this.value)" placeholder="${t('I-search ang bayan o produkto…','Search town or product…')}" aria-label="Search cooperatives"><button class="btn soft icon-label" onclick="go('map')">${icon('map')}<span class="btn-label">${t('Mapa','Map')}</span></button></div><div id="coopResults">${coopCards(list)}</div></section>`}
function coopCards(list){return list.length?list.map((c,i)=>`<article class="card listing"><img src="assets/cooperatives-reference.jpg" alt="${esc(c.name)} cooperative" style="object-position:center ${i? '76%':'38%'}"><div class="listing-body"><h3>${c.name}</h3><p class="muted">⌖ ${c.place} (${c.dist})</p><p class="muted">♧ ${c.members} ${t('Kasapi','members')}</p>${c.tags.map(x=>`<span class="tag">${x}</span>`).join('')}<button class="btn soft wide" onclick="go('map')">${icon('map')}<span class="btn-label">${t('Tingnan sa mapa','View on map')}</span></button></div></article>`).join(''):`<p class="empty">${t('Walang kooperatibang tumutugma sa search.','No cooperatives match this search.')}</p>`}
function filterButton(kind,id,label){const active=(kind==='coop'?state.coopFilter:state.harvestFilter)|| (kind==='coop'?'nearest':'all');return `<button class="${active===id?'active':''}" onclick="setFilter('${kind}','${id}')">${label}</button>`}
function setFilter(kind,value){if(kind==='coop')state.coopFilter=value;else state.harvestFilter=value;render()}
function searchCoops(value){state.coopQuery=value;const element=document.querySelector('#coopResults');if(element){const query=value.toLowerCase();const list=[...coops].filter(c=>`${c.name} ${c.place} ${c.tags.join(' ')}`.toLowerCase().includes(query)).sort((a,b)=>Number(a.dist)-Number(b.dist));element.innerHTML=coopCards(list)}}
function openPriceEstimator(crop,low,high){state.estimateCrop=crop||null;state.estimateGuide=crop?{low:Number(low),high:Number(high)}:null;state.estimateFromPrices=true;state.page='estimate';render();window.scrollTo({top:0,behavior:'smooth'})}
function estimator(){const selected=state.estimateCrop||'palay',chosen=crops.find(c=>c.id===selected),options=crops.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${isEn()?c.en:c.fil}</option>`).join(''),guide=state.estimateGuide&&chosen?`<div class="selected-price-guide">${cropPhoto(chosen,'selected-crop-photo')}<div><small>${t('Pinili mula sa Presyo Ngayon','Selected from Today’s Prices')}</small><b>${isEn()?chosen.en:chosen.fil}</b><span>${state.estimateGuide.low===state.estimateGuide.high?money(state.estimateGuide.low):`${money(state.estimateGuide.low)}–${money(state.estimateGuide.high)}`} / ${t('kilo','kg')}</span></div></div>`:'';return `<section class="page estimator"><div class="topbar"><button class="back" onclick="go('${state.estimateFromPrices?'prices':'home'}')">${icon('back',24)}</button><h1>AI ${t('Tantiya ng Presyo','Price Estimator')}</h1>${authHeader()}</div>${guide}<p class="muted">${t('Kumpletuhin ang dami, kalidad, lokasyon, at petsa upang makuha ang tantiya.','Complete the quantity, quality, location, and date to receive the estimate.')}</p><form class="card" onsubmit="estimate(event)"><div class="field"><label for="crop">${t('Pananim','Crop')}</label><select id="crop" onchange="state.estimateCrop=this.value;state.estimateGuide=null;document.querySelector('.selected-price-guide')?.remove()">${options}</select></div><div class="field"><label for="quality">${t('Kalidad','Quality')}</label><select id="quality"><option value="premium">${t('Premium / Class A','Premium / Class A')}</option><option value="standard">${t('Karaniwan / Class B','Standard / Class B')}</option><option value="low">${t('Mababa / Class C','Lower / Class C')}</option></select></div><div class="field"><label for="quantity">${t('Dami (kg)','Quantity (kg)')}</label><input id="quantity" type="number" min="1" required value="500"></div><div class="field"><label for="estimateLocation">${t('Lokasyon','Location')}</label><input id="estimateLocation" required value="${esc(state.user?.location||'Pilipinas')}"></div><div class="field"><label for="harvestDate">${t('Target na petsa ng ani','Expected harvest date')}</label><input id="harvestDate" type="date" required></div><button class="btn wide" id="estimateButton">✦ ${t('Kunin ang AI na tantiya','Get AI estimate')}</button></form><div id="estimateResult"></div><p class="notice">${t('Hindi ito garantiya ng presyo. Magpasya batay sa aktwal na kondisyon ng merkado at mga buyer.','This is not a price guarantee. Make decisions based on local market conditions and buyers.')}</p></section>`}
async function estimate(e){e.preventDefault();const b=$('#estimateButton'),quantity=Number($('#quantity').value);b.disabled=true;b.textContent=t('Sinusuri ng AI…','AI is analyzing…');try{const data=await api('/api/estimate',{crop:$('#crop').value,quality:$('#quality').value,quantity,location:$('#estimateLocation').value,harvestDate:$('#harvestDate').value,language:state.lang}),totalMinimum=data.totalMinimum??data.minimum*quantity,totalMaximum=data.totalMaximum??data.maximum*quantity;$('#estimateResult').innerHTML=`<section class="estimate card"><div class="eyebrow">${data.source==='openai'?'AI-powered':t('Market guidance','Market guidance')}</div><span class="range">₱${data.minimum}–₱${data.maximum}</span><p>${t('bawat kilo','per kilogram')}</p><div class="estimate-total"><span>${t(`Kabuuang tantiya para sa ${quantity} kg`,`Estimated total for ${quantity} kg`)}</span><strong>${money(totalMinimum)}–${money(totalMaximum)}</strong></div><div class="row between"><span class="small">${t('Kumpiyansa','Confidence')}</span><b>${data.confidence}%</b></div><div class="meter"><i style="width:${data.confidence}%"></i></div><p><b>${t('Pinakamainam na oras','Best timing')}:</b> ${esc(data.bestTime)}</p><ul class="tips">${data.tips.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`;toast(t('Tapos na ang tantiya.','Estimate ready.'))}catch(err){toast(err.message)}finally{b.disabled=false;b.textContent=`✦ ${t('Kunin ang AI na tantiya','Get AI estimate')}`}}
function mapPage(){const u=state.user||{};const query=encodeURIComponent(`${u.location||'Philippines'} agricultural cooperatives`);return `<section class="page soft-page"><div class="topbar"><button class="back" onclick="go('home')">${icon('back')}</button><h1>${t('Mapa ng mga Katuwang','Partner Map')}</h1>${authHeader()}</div><p class="muted">${t('I-drag, i-scroll, o i-zoom ang mapa upang makita ang mga magsasaka, buyer, at kooperatiba malapit sa iyo.','Drag, scroll, or zoom the map to explore farmers, buyers, and cooperatives near you.')}</p><div class="card map-card"><iframe class="map" title="Interactive Google Maps" loading="lazy" allowfullscreen referrerpolicy="no-referrer-when-downgrade" src="https://www.google.com/maps?q=${query}&output=embed"></iframe><p class="map-caption">${icon('map',15)} Google Maps · ${esc(u.location||'Philippines')} · ${t('Interactive map','Interactive map')}</p></div><div class="card"><h3>${t('Mga malapit na lugar','Nearby places')}</h3><p class="muted">🤝 Banaue Organic Rice Coop · 2.4 km</p><p class="muted">🛒 Bulacan Organic Wholesalers · 4.1 km</p><p class="muted">🌾 ${t('Mga paparating na ani','Upcoming harvests')} · 3 ${t('nakalista','listed')}</p></div></section>`}
function buyerFilterButton(id,label){return `<button class="${(state.buyerFilter||'nearest')===id?'active':''}" onclick="setBuyerFilter('${id}')">${label}</button>`}
function setBuyerFilter(value){state.buyerFilter=value;render()}
function pricesPage(){const data=marketData();return `<section class="page soft-page prices-page"><div class="topbar"><button class="back" onclick="go('home')">${icon('back',24)}</button><h1>${t('Lahat ng Presyo Ngayon','All Prices Today')}</h1>${authHeader()}</div><p class="page-intro">${t('Pindutin ang isang produkto upang direktang buksan ang AI price estimator. Kumpirmahin pa rin ang presyo sa buyer bago magbenta.','Tap a product to open the AI price estimator directly. Still confirm the price with the buyer before selling.')}</p><div class="price-list">${crops.map(c=>{const live=data.listings.filter(l=>l.crop===c.id&&l.status==='available'),values=live.map(l=>l.price),low=values.length?Math.min(...values):c.base,high=values.length?Math.max(...values):c.base,name=isEn()?c.en:c.fil;return `<button type="button" class="card price-list-item" onclick="openPriceEstimator('${c.id}',${low},${high})" aria-label="${esc(t(`Buksan ang AI price estimator para sa ${name}`,`Open AI price estimator for ${name}`))}">${cropPhoto(c,'price-list-photo')}<span class="price-list-copy"><b>${name}</b><small>${live.length?t('Batay sa mga aktibong listing','Based on active listings'):t('Gabay na presyo','Guide price')}</small></span><strong>${low===high?money(low):`${money(low)}–${money(high)}`}<small>/${t('kilo','kg')}</small></strong><span class="price-card-arrow" aria-hidden="true">${icon('chevron',24)}</span></button>`}).join('')}</div><button class="btn soft wide" onclick="openPriceEstimator()">✦ ${t('Pumili sa AI estimator','Choose inside AI estimator')}</button></section>`}
const cropPlans={
  palay:{months:[5,6,11,12],days:[110,130],tip:['Simulan sa umaga at tiyaking may sapat na tubig sa punlaan.','Start in the morning and make sure the seedbed has enough water.']},
  mais:{months:[5,6,10,11],days:[95,110],tip:['Magtanim kapag mamasa-masa ang lupa ngunit hindi lubog sa tubig.','Plant when the soil is moist but not waterlogged.']},
  kamatis:{months:[10,11,12,1],days:[90,120],tip:['Mas mainam ang malamig at hindi masyadong maulang panahon.','Cooler, less rainy months are usually best.']},
  sibuyas:{months:[10,11],days:[100,120],tip:['Iwasan ang panahong palaging basa upang mabawasan ang pagkabulok.','Avoid persistently wet conditions to reduce bulb rot.']},
  saging:{months:[5,6,7],days:[270,360],tip:['Itanim sa simula ng tag-ulan sa lupang mabilis maglabas ng sobrang tubig.','Plant near the start of the rainy season in well-drained soil.']},
  talong:{months:[10,11,12,1,5,6],days:[90,120],tip:['Panatilihing mamasa-masa ang lupa at bantayan ang fruit borer.','Keep the soil evenly moist and monitor for fruit borers.']},
  sili:{months:[10,11,12,1],days:[90,120],tip:['Iwasan ang sobrang tubig at tiyaking may maayos na drainage.','Avoid overwatering and provide good drainage.']},
  pechay:{months:[10,11,12,1,2],days:[30,45],tip:['Diligan nang regular at anihin habang malambot pa ang mga dahon.','Water regularly and harvest while the leaves are tender.']},
  repolyo:{months:[10,11,12,1],days:[90,120],tip:['Pinakamainam sa malamig na lugar at lupang may magandang drainage.','Best suited to cool areas with well-drained soil.']},
  patatas:{months:[10,11,12],days:[90,120],tip:['Gumamit ng maluwag na lupa at iwasang mababad sa tubig ang tuber.','Use loose soil and keep developing tubers from becoming waterlogged.']},
  kamote:{months:[5,6,7,10,11],days:[100,140],tip:['Magtanim sa maluwag na lupa upang lumaki nang maayos ang mga ugat.','Plant in loose soil so storage roots can develop well.']},
  mangga:{months:[5,6,7],days:[1095,1825],tip:['Pumili ng maaraw at hindi binabahang lugar para sa punla.','Choose a sunny, flood-free site for young trees.']},
  pinya:{months:[3,4,5,6],days:[450,540],tip:['Gumamit ng lupang mabilis mag-drain at iwasan ang nakatigil na tubig.','Use fast-draining soil and avoid standing water.']},
  papaya:{months:[5,6,7],days:[240,300],tip:['Magtanim sa maaraw na lugar at protektahan laban sa malakas na hangin.','Plant in full sun and protect plants from strong winds.']},
  niyog:{months:[5,6,7],days:[1460,2190],tip:['Ihanda ang malalim at maayos na hukay at tiyaking may sapat na espasyo.','Prepare a deep planting hole and allow adequate spacing.']}
};
function addDays(date,days){const d=new Date(date);d.setDate(d.getDate()+days);return d}
function readableDate(date){return new Intl.DateTimeFormat(isEn()?'en-PH':'fil-PH',{year:'numeric',month:'long',day:'numeric'}).format(date)}
function nextPlantingWindow(months){const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate());if(months.includes(now.getMonth()+1)&&now.getDate()<=21)return {start:today,end:new Date(now.getFullYear(),now.getMonth(),21)};const ordered=[];for(let y=now.getFullYear();y<=now.getFullYear()+1;y++)for(const m of months)ordered.push(new Date(y,m-1,1));const start=ordered.sort((a,b)=>a-b).find(d=>d>today)||ordered[0];return {start,end:new Date(start.getFullYear(),start.getMonth(),21)}}
function buildCropPlan(crop){const guide=cropPlans[crop],window=nextPlantingWindow(guide.months);return {crop,plantStart:window.start,plantEnd:window.end,harvestStart:addDays(window.start,guide.days[0]),harvestEnd:addDays(window.end,guide.days[1]),tip:t(...guide.tip)}}
function planPage(){const selected=state.planCrop||'palay',result=state.cropPlanResult;return `<section class="page soft-page plan-page"><div class="topbar"><button class="back" onclick="go('home')">${icon('back',24)}</button><h1>${t('Plano sa Pagtatanim','Crop Planning')}</h1>${authHeader()}</div><p class="page-intro">${t('Piliin ang itatanim upang makita ang pinakamainam na panahon ng pagtatanim at tinatayang panahon ng pag-ani.','Choose what you will plant to see the recommended planting and estimated harvest periods.')}</p><form class="card plan-form" onsubmit="createCropPlan(event)"><div class="field"><label for="planCrop">${t('Ano ang iyong itatanim?','What will you plant?')}</label><select id="planCrop">${crops.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${isEn()?c.en:c.fil}</option>`).join('')}</select></div><div class="field"><label for="planLocation">${t('Saan ka magtatanim?','Where will you plant?')}</label><input id="planLocation" value="${esc(state.planLocation||state.user?.location||'Pilipinas')}" required></div><button class="btn wide" type="submit">📅 ${t('Gumawa ng plano','Show planting plan')}</button></form>${result?`<section class="card plan-result" aria-live="polite"><div class="plan-crop">${cropName(result.crop)}</div><div class="timeline-step"><span>1</span><div><small>${t('PINAKAMAINAM NA PAGTATANIM','RECOMMENDED PLANTING')}</small><strong>${readableDate(result.plantStart)} – ${readableDate(result.plantEnd)}</strong><p>${t('Magtanim sa umaga o hapon upang iwasan ang matinding init.','Plant in the morning or late afternoon to avoid extreme heat.')}</p></div></div><div class="timeline-line"></div><div class="timeline-step harvest-step"><span>2</span><div><small>${t('TINATAYANG PAG-ANI','ESTIMATED HARVEST')}</small><strong>${readableDate(result.harvestStart)} – ${readableDate(result.harvestEnd)}</strong><p>${result.tip}</p></div></div><p class="notice">${t('Gabay ito batay sa karaniwang panahon ng tanim sa Pilipinas. Iangkop sa lokal na panahon, variety, lupa, at payo ng municipal agriculturist.','This guide uses common Philippine growing seasons. Adjust for local weather, variety, soil, and advice from your municipal agriculturist.')}</p></section>`:''}</section>`}
function createCropPlan(e){e.preventDefault();state.planCrop=$('#planCrop').value;state.planLocation=$('#planLocation').value.trim();state.cropPlanResult=buildCropPlan(state.planCrop);render();toast(t('Handa na ang plano sa pagtatanim.','Your crop plan is ready.'))}
function communityPage(){return `<section class="page soft-page"><div class="topbar"><button class="back" onclick="go('home')">‹</button><h1>${t('Pamayanan','Community')}</h1>${authHeader()}</div><p class="muted">${t('Koneksyon at kaalaman ng magsasakang Pilipino','Connection and knowledge for Filipino farmers')}</p>${[['Ramon Dimaculangan','Rice Farmer · Batangas','Salamat sa payo ng AgrikAIzen! Tumaas ang average yield ng aming RC 218 rice ng halos 18% kumpara noong nakaraang taon.','#UlatAni'],['Maria Santos','Agronomist · Benguet Coop','Mag-ingat sa peste ng Rice Black Bug ngayong papalapit ang kabilugan ng buwan.','#AgronomiyaTip']].map((p,i)=>`<article class="card post"><div class="row"><div class="partner-avatar">${i?'👩🏽‍🌾':'👨🏽‍🌾'}</div><div><b>${p[0]}</b><p class="muted small">${p[1]} · ${i?'5h':'2h'} ${t('nakaraan','ago')}</p></div></div><p>${p[2]}</p>${!i?'<div class="post-photo">🌾</div>':''}<span class="tag">${p[3]}</span><p class="muted">♡ ${i?'32':'48'}　◯ ${i?'5':'12'}　⌯</p></article>`).join('')}</section>`}
function oversupplyPage(){const methods=[
  {icon:'sun',title:t('Pagpapatuyo','Drying'),intro:t('Mainam para sa kamatis, sili, mangga, at saging.','Good for tomatoes, chilies, mangoes, and bananas.'),time:t('2–3 araw, depende sa panahon','2–3 days, depending on weather'),crops:t('Kamatis, sili, mangga, saging','Tomato, chili, mango, banana'),tools:t('Malinis na kutsilyo, tray o screen, pantakip na net, at solar dryer kung mayroon.','Clean knife, trays or screens, protective mesh, and a solar dryer if available.'),steps:[t('Piliin ang sariwa at walang amag. Hugasan at hiwain nang magkakapareho.','Choose fresh produce without mold. Wash and cut into even pieces.'),t('Ilatag nang isang patong at takpan laban sa alikabok at insekto.','Arrange in one layer and protect from dust and insects.'),t('Patuyuin hanggang walang basang bahagi, palamigin, saka ilagay sa malinis at airtight na lalagyan.','Dry until no wet areas remain, cool, then pack in a clean airtight container.')],storage:t('Lagyan ng petsa at itago sa malamig at tuyong lugar. Itapon kapag may amag, kakaibang amoy, o kahalumigmigan.','Label with the date and store in a cool, dry place. Discard if mold, unusual odor, or moisture appears.')},
  {icon:'jar',title:t('Pag-aatsara','Pickling'),intro:t('Mainam para sa papaya, singkamas, pipino, carrots, at sili.','Good for papaya, turnip, cucumber, carrots, and chilies.'),time:t('1 araw na paghahanda','1 day preparation'),crops:t('Papaya, singkamas, pipino, carrots, sili','Papaya, turnip, cucumber, carrots, chili'),tools:t('Malinis na garapon, stainless na kaldero, food-grade vinegar, asin, at malinis na sandok.','Clean jars, a stainless pot, food-grade vinegar, salt, and a clean ladle.'),steps:[t('Hugasan, balatan kung kailangan, at hiwain ang sariwang ani.','Wash, peel if needed, and cut fresh produce.'),t('Gumamit ng subok na recipe at eksaktong sukat ng suka, tubig, asin, at asukal.','Use a tested recipe and exact measures of vinegar, water, salt, and sugar.'),t('Ilagay sa malinis na garapon at palamigin agad maliban kung gumamit ng validated canning process.','Pack into clean jars and refrigerate promptly unless using a validated canning process.')],storage:t('Panatilihing refrigerated. Huwag tikman kapag umalsa ang takip, bumula nang hindi inaasahan, o may kakaibang amoy.','Keep refrigerated. Do not taste if the lid bulges, unexpected bubbling occurs, or the odor is unusual.')},
  {icon:'sauce',title:t('Juice o Sarsa','Juice or Sauce'),intro:t('Mainam para sa sobrang kamatis, mangga, pinya, at papaya.','Good for excess tomatoes, mangoes, pineapples, and papayas.'),time:t('3–5 oras','3–5 hours'),crops:t('Kamatis, mangga, pinya, papaya','Tomato, mango, pineapple, papaya'),tools:t('Kutsilyo, blender o food mill, stainless na kaldero, sandok, at malinis na bote.','Knife, blender or food mill, stainless pot, ladle, and clean bottles.'),steps:[t('Hugasan at alisin ang bulok o may amag na bahagi; huwag isama ang sirang prutas.','Wash and discard rotten or moldy produce; do not process spoiled fruit.'),t('Durugin o i-blend, saka lutuin ayon sa subok na recipe.','Puree or blend, then cook using a tested recipe.'),t('Ilagay sa angkop at malinis na lalagyan, palamigin nang ligtas, at ilagay agad sa refrigerator.','Fill suitable clean containers, cool safely, and refrigerate promptly.')],storage:t('Lagyan ng petsa at panatilihing malamig. Para sa produktong ibebenta, magpatulong sa DOST, DA, o local food-safety officer sa shelf-life at packaging.','Date and keep chilled. For products intended for sale, ask DOST, DA, or a local food-safety officer about shelf life and packaging.')},
  {icon:'grain',title:t('Pag-giling bilang Harina','Milling into Flour'),intro:t('Maaaring gawing harina ang kamote o saging kapag maayos na pinatuyo.','Sweet potato or banana can become flour after thorough drying.'),time:t('1–2 araw','1–2 days'),crops:t('Kamote, saging','Sweet potato, banana'),tools:t('Peeler, slicer, drying tray o dryer, grinder, salaan, at airtight na lalagyan.','Peeler, slicer, drying trays or dryer, grinder, sieve, and airtight container.'),steps:[t('Hugasan, balatan, at hiwain nang manipis at pantay.','Wash, peel, and slice thinly and evenly.'),t('Patuyuin nang lubos bago gilingin upang maiwasan ang amag.','Dry completely before grinding to reduce mold risk.'),t('Gilingin, salain, palamigin, at isara sa malinis at tuyong lalagyan.','Grind, sift, cool, and seal in a clean, dry container.')],storage:t('Itago sa malamig at tuyong lugar. Itapon kapag namuo dahil sa basa, inamoy-panisan, o may insekto.','Store in a cool, dry place. Discard if it clumps from moisture, smells stale, or contains insects.')}
];return `<section class="page soft-page"><div class="topbar"><button class="back" onclick="go('home')" aria-label="${t('Bumalik','Back')}">${icon('back',24)}</button><h1>${t('Iwas-Tapon Solusyon','Save-the-Harvest Solutions')}</h1></div><div class="eyebrow">${t('Gabay sa oversupply','Oversupply guide')}</div><section class="process-hero"><span>${icon('sparkle',16)} AI ${t('Rekomendasyon','Recommendation')}</span><h2>${t('Iproseso ang sobrang ani upang maiwasan ang lugi','Process excess harvest to avoid losses')}</h2></section><h2>${t('Mga Pamamaraan ng Pagpoproseso','Processing methods')}</h2><p class="page-intro">${t('Pindutin ang bawat paraan upang makita ang mga hakbang at kailangang kagamitan.','Tap each method to see the steps and materials needed.')}</p>${methods.map((m,i)=>`<details class="card process-card" ${i===0?'open':''}><summary><span class="process-icon">${icon(m.icon,28)}</span><span class="grow"><b>${m.title}</b><small>${m.intro}</small><em>◷ ${m.time}</em></span><span class="process-chevron">${icon('chevron',26)}</span></summary><div class="process-details"><div class="process-facts"><p><b>🌱 ${t('Bagay na ani','Suitable crops')}</b><span>${m.crops}</span></p><p><b>🧰 ${t('Kagamitan','Materials')}</b><span>${m.tools}</span></p></div><h3>${t('Mga hakbang','Steps')}</h3><ol>${m.steps.map(step=>`<li>${step}</li>`).join('')}</ol><p class="process-storage"><b>✓ ${t('Pag-iimbak at kaligtasan','Storage and safety')}</b><span>${m.storage}</span></p></div></details>`).join('')}<p class="notice">${t('Gabay lamang ito. Para sa maramihang produksyon o pagbebenta, kumonsulta sa municipal agriculturist, DOST, DA, o local food-safety officer.','This is general guidance. For large-batch production or selling, consult your municipal agriculturist, DOST, DA, or local food-safety officer.')}</p></section>`}
function reviewPage(){return `<section class="page soft-page review"><div class="topbar"><button class="back" onclick="go('home')">‹</button><h1>${t('Suriin ang Alok','Review Offer')}</h1></div><h2>⚠ ${t('Mababa ang Presyo!','Low Price!')}</h2><p>${t('Inalok na presyo ay mababa sa fair market value.','The offer is below the fair market value.')}</p><div class="card offer"><div><span>${t('Alok ng Trader','Trader offer')}</span><strong>₱18.00</strong><small>${t('bawat kilo','per kg')}</small></div><div><span>Fair Price (AI)</span><strong>₱25.00</strong><small>${t('bawat kilo','per kg')}</small></div></div><h2>${t('Inirerekomendang Hakbang','Recommended steps')}</h2>${[t('Bumahagi sa pinakamalapit na Kooperatiba','Share with the nearest cooperative'),t('Suriin ang direktang mamimili sa AgrikAIzen','Browse direct buyers in AgrikAIzen'),t('Humiling ng panibagong AI Quality Check','Request another AI quality check')].map(x=>`<button class="card action-row">♧ <b>${x}</b><span>›</span></button>`).join('')}<button class="btn wide" onclick="go('buyers')">${t('Hanapin ang Ibang Mamimili','Find Other Buyers')}</button></section>`}
function profileMediaKey(){return `agri_profile_media_${state.user?.id||'guest'}`}
function validProfileImage(value){return typeof value==='string'&&/^data:image\/(?:jpeg|png|webp);base64,[a-z0-9+/=]+$/i.test(value)}
function profileMedia(){const saved=readStoredJson(profileMediaKey(),{});return {avatar:validProfileImage(saved?.avatar)?saved.avatar:null,cover:validProfileImage(saved?.cover)?saved.cover:null}}
function profileInitials(name){return String(name||'A').trim().split(/\s+/).slice(0,2).map(part=>part[0]||'').join('').toUpperCase()||'A'}
function resizeProfileImage(file,kind){return new Promise((resolve,reject)=>{if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))return reject(new Error(t('Pumili ng JPG, PNG, o WebP na larawan.','Choose a JPG, PNG, or WebP image.')));if(file.size>8*1024*1024)return reject(new Error(t('Hanggang 8 MB lamang ang larawan.','The image must be 8 MB or smaller.')));const reader=new FileReader();reader.onerror=()=>reject(new Error(t('Hindi mabasa ang larawan.','The image could not be read.')));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error(t('Hindi wastong image file.','This is not a valid image file.')));image.onload=()=>{const width=kind==='avatar'?512:1200,height=kind==='avatar'?512:400,scale=Math.max(width/image.naturalWidth,height/image.naturalHeight),sourceWidth=width/scale,sourceHeight=height/scale,sourceX=(image.naturalWidth-sourceWidth)/2,sourceY=(image.naturalHeight-sourceHeight)/2,canvas=document.createElement('canvas'),context=canvas.getContext('2d');canvas.width=width;canvas.height=height;context.fillStyle='#eef5e5';context.fillRect(0,0,width,height);context.drawImage(image,sourceX,sourceY,sourceWidth,sourceHeight,0,0,width,height);resolve(canvas.toDataURL('image/jpeg',.84))};image.src=reader.result};reader.readAsDataURL(file)})}
async function saveProfileImage(event,kind){const input=event.target,file=input.files?.[0];if(!file)return;input.disabled=true;try{const image=await resizeProfileImage(file,kind),media=profileMedia();media[kind]=image;localStorage.setItem(profileMediaKey(),JSON.stringify(media));render();toast(kind==='avatar'?t('Na-save ang profile picture.','Profile picture saved.'):t('Na-save ang cover picture.','Cover picture saved.'))}catch(error){toast(error.message)}finally{input.disabled=false;input.value=''}}
function removeProfileImage(kind){const media=profileMedia();delete media[kind];localStorage.setItem(profileMediaKey(),JSON.stringify(media));render();toast(kind==='avatar'?t('Ibinalik ang default profile picture.','Default profile picture restored.'):t('Ibinalik ang default cover.','Default cover restored.'))}
function showProfilePhotoControl(kind){state.profilePhotoControl=state.profilePhotoControl===kind?'':kind;render()}
function legacyProfile(){const u=state.user||{},media=profileMedia(),control=state.profilePhotoControl||'',cover=media.cover||'/assets/profile-cover-v2.jpg',avatar=media.avatar?`<img class="avatar" src="${media.avatar}" alt="${t('Profile picture','Profile picture')}">`:`<div class="avatar avatar-placeholder" role="img" aria-label="${t('Default profile picture','Default profile picture')}">${esc(profileInitials(u.name))}</div>`;return `<section class="page"><button class="profile-cover" type="button" style="--profile-cover:url('${cover}')" onclick="showProfilePhotoControl('cover')" aria-label="${t('Palitan ang cover picture','Change cover picture')}"></button><section class="card profile-card"><button class="avatar-shell" type="button" onclick="showProfilePhotoControl('avatar')" aria-label="${t('Palitan ang profile picture','Change profile picture')}">${avatar}</button><h1>${esc(u.name||'AgrikAIzen Member')}</h1><p class="muted">⌖ ${esc(u.location||'Pilipinas')}</p><span class="tag">${roleName(u.role)}</span><span class="tag">${t('Miyembro mula','Member since')} ${new Date().getFullYear()}</span>${control?`<div class="profile-photo-controls"><label class="btn soft profile-photo-control">${icon('camera')}<span>${control==='avatar'?(media.avatar?t('Palitan ang profile picture','Change profile picture'):t('Maglagay ng profile picture','Add profile picture')):t('Palitan ang cover picture','Change cover picture')}</span><input class="sr-only" type="file" accept="image/jpeg,image/png,image/webp" onchange="saveProfileImage(event,'${control}')"></label></div>${control==='avatar'&&media.avatar?`<div class="profile-photo-resets"><button class="link" type="button" onclick="removeProfileImage('avatar')">${t('Alisin ang profile picture','Remove profile picture')}</button></div>`:''}${control==='cover'&&media.cover?`<div class="profile-photo-resets"><button class="link" type="button" onclick="removeProfileImage('cover')">${t('Ibalik ang default cover','Restore default cover')}</button></div>`:''}`:''}<p class="notice profile-photo-note">${t('Ang mga larawan ay naka-save sa browser na ito. Gumamit ng malinaw na larawan na hanggang 8 MB.','Photos are saved in this browser. Use a clear image up to 8 MB.')}</p><div class="stat-grid profile-stats" style="margin-top:16px"><div class="stat"><b>14</b><span>${t('Kabuuang ani','Harvests')}</span></div><div class="stat"><b>₱150k</b><span>${t('Kita','Income')}</span></div></div></section><div class="section-title"><h2>${t('Mga gantimpala','Achievements')}</h2></div><div class="awards"><div class="award"><span>🌾</span>Super Harvest</div><div class="award"><span>🤝</span>Coop Leader</div><div class="award"><span>🤖</span>AI Adopter</div></div><div class="section-title"><h2>${t('Huling aktibidad','Recent activity')}</h2></div><div class="card activity"><span class="ico">🌱</span><div><b>${t('Nagamit ang AI Price Estimator','Used AI Price Estimator')}</b><p class="muted small">${t('Ngayon','Today')}</p></div></div><button class="btn ghost wide" onclick="go('map')">⌖ ${t('Aking lokasyon sa mapa','My location on map')}</button><button class="btn danger wide" onclick="logout()">${t('Mag-log out','Sign out')}</button></section>`}
function contact(name){toast(`${t('Naipadala ang request kay','Request sent to')} ${name}`)}
function go(page){const previous=state.page;if(page==='estimate'&&previous!=='prices')state.estimateFromPrices=false;state.page=page;state.formInteractionUntil=0;render();if(['home','prices','buyers','profile','harvests','offers','logistics','premium'].includes(page))refreshMarket();if(page==='community'&&typeof refreshCommunity==='function')refreshCommunity();if(['intelligence','assisted'].includes(page)&&typeof refreshIntelligence==='function')refreshIntelligence(page==='intelligence');window.scrollTo({top:0,behavior:'smooth'})}function logout(){state.draft=null;state.listingEstimate=null;state.market=null;state.community=null;state.intelligence=null;state.user=null;state.token='';localStorage.removeItem('agri_user');localStorage.removeItem('agri_token');state.mode='login';state.page='home';state.draft=null;state.listingEstimate=null;render();toast(t('Naka-log out ka na.','You have been signed out.'))}
function render(){if(document.documentElement)document.documentElement.lang=state.lang;let content;if(!state.user)content=auth();else{let view={home,prices:pricesPage,harvests:harvestsPage,coops:coopsPage,estimate:estimator,intelligence:typeof intelligencePage==='function'?intelligencePage:home,assisted:typeof assistedPage==='function'?assistedPage:home,map:mapPage,profile,submit:submitHarvest,listingEstimate:listingEstimate,offers:offersPage,logistics:logisticsPage,premium:premiumPage,buyers:buyersPage,plan:planPage,community:communityPage,oversupply:oversupplyPage,review:reviewPage}[state.page]||home;content=`${view()}${nav()}`}$('#app').innerHTML=content}
window.selectLanguage=selectLanguage;window.toggleLanguageMenu=toggleLanguageMenu;window.toggleAuth=toggleAuth;window.setRole=setRole;window.submitAuth=submitAuth;window.setFilter=setFilter;window.setBuyerFilter=setBuyerFilter;window.searchCoops=searchCoops;window.go=go;window.estimate=estimate;window.createCropPlan=createCropPlan;window.contact=contact;window.logout=logout;
$('#app').innerHTML=splash();setTimeout(()=>{render();if(state.user)refreshMarket()},700);
